    "19": "श्री मदभागवत् के दशवें स्कंद के 51 वें अध्याय में स्वयं श्री कृष्ण ने कहा है कि श्री वासुदेव का पुत्रा होने के कारण मुझे वासुदेव कहते हैं, न की सर्व का मालिक या सर्व व्यापक होने के कारण अर्थात् वासुदेव पूर्ण परमात्मा है।",
