    "ब्रह्म": "है व तीनों गुण अर्थात् रजगुण ब्रह्मा जी, सतगुण विष्णु जी, तमगुण शिव जी रूपी शाखायें हैं। वृृक्ष को मूल",
    "ब्रह्": "है व तीनों गुण अर्थात् रजगुण ब्रह्मा जी, सतगुण विष्णु जी, तमगुण शिव जी रूपी शाखायें हैं। वृृक्ष को मूल",
    "जड़": "से ही खुराक अर्थात् आहार प्राप्त होता है। जैसे हम आम का पौधा लगायेंगे तो मूल को सीचेंगे, जड़ से खुराक तना में जायेगी, तना से मोटी डार में, डार से शाखाओं में जायेगी, फिर उन शाखाओं को फल लगेंगे, फिर वह टहनियां अपने आप फल देंगी। इसी प्रकार पूर्णब्रह्म अर्थात् परम अक्षर ब्रह्म रूपी मूल की पूजा अर्थात् सिंचाई करने से अक्षर पुरुष अर्थात् परब्रह्म रूपी तना में संस्कार अर्थात् खुराक जायेगी, फिर अक्षर पुरुष से क्षर पुरुष अर्थात् ब्रह्म रूपी डार में संस्कार अर्थात् खुराक जायेगी। फिर ब्रह्म से तीनों गुण अर्थात् श्री ब्रह्मा जी, श्री विष्णु जी, श्री शिव जी रूपी तीनों शाखाओं में संस्कार अर्थात् खुराक जायेगी। फिर इन तीनों देवताओं रूपी टहनियों को फल लगेंगे अर्थात् फिर तीनों प्रभु श्री ब्रह्मा जी, श्री विष्णु जी, श्री शिव जी हमें संस्कार आधार पर ही कर्म फल देते हैं। यही प्रमाण गीता अध्याय 15 श्लोक 16 व 17 में भी है कि दो प्रभु इस पृथ्वी लोक में है, एक क्षर पुरुष अर्थात् ब्रह्म, दूसरा अक्षर पुरुष अर्थात् परब्रह्म। ये दोनों प्रभु तथा इनके लोक में सर्व प्राणी तो नाशवान हैं, वास्तव में अविनाशी तथा तीनों लोकों में प्रवेश करके सर्व का धारण-पोषण करने वाला परमेश्वर परमात्मा तो उपरोक्त दोनों भगवानों से भिन्न है।",
