    "कर्तारम्": "कत्र्ता",
    "कर्तारम": "कत्र्ता",
    "अकर्तारम्": "अकत्र्ता है। भावार्थः- गीता अध्याय 3 श्लोक 14-15 में गीता ज्ञान दाता ने कहा है कि कर्मों को ब्रह्मोद्धवम अर्थात् ब्रह्म से उत्पन्न जान। यही प्रमाण इस अध्याय 4 श्लोक 13 में है। गीता ज्ञान दाता काल ब्रह्म कह रहा है कि चार वर्णों की व्यवस्था मैंने की है। इनके कर्मों का विभाजन भी मैंने किया है। वह अविनाशी पूर्ण परमात्मा इन कर्मों का अकर्ता है, ब्रह्मा रजगुण, विष्णु सतगुण तथा शिव तमगुण के विभाग भी काल ब्रह्म ने बनाए हैं सृृष्टि, स्थिती, संहार। इनका करने वाला अविनाशी परमात्मा नहीं है।",
    "अकर्तारम": "अकत्र्ता है। भावार्थः- गीता अध्याय 3 श्लोक 14-15 में गीता ज्ञान दाता ने कहा है कि कर्मों को ब्रह्मोद्धवम अर्थात् ब्रह्म से उत्पन्न जान। यही प्रमाण इस अध्याय 4 श्लोक 13 में है। गीता ज्ञान दाता काल ब्रह्म कह रहा है कि चार वर्णों की व्यवस्था मैंने की है। इनके कर्मों का विभाजन भी मैंने किया है। वह अविनाशी पूर्ण परमात्मा इन कर्मों का अकर्ता है, ब्रह्मा रजगुण, विष्णु सतगुण तथा शिव तमगुण के विभाग भी काल ब्रह्म ने बनाए हैं सृृष्टि, स्थिती, संहार। इनका करने वाला अविनाशी परमात्मा नहीं है।",
