    "बध्यते": "बंधता अर्थात् गीता अध्याय 4 श्लोक 34 में कहे तत्वदर्शी संत की खोज करके गीता अध्याय 18 श्लोक 62 में कहे उस परमात्मा की शरण में जाकर पूर्ण परमात्मा की भक्ति करके कर्मों के बन्धन से मुक्त हो जाता है।",
