    "किल्बिषम्": "क्योंकि शास्त्र विधि त्याग कर मनमाना आचरण अर्थात् पूजा करने वालों को गीता अध्याय 7 श्लोक 12 से 15 में राक्षस स्वभाव को धारण किए हुए, मनुष्यों में नीच, दूषित कर्म अर्थात् शास्त्रा विधि त्याग कर मनमाना आचरण करने वाले, मूर्ख मेरी भक्ति भी नहीं करते, वे केलव तीनों गुणों अर्थात् रजगुण ब्रह्मा जी, सतगुण विष्णु जी, तमगुण शिव जी की भक्ति करके उनसे मिलने वाली क्षणिक राहत पर आश्रित रहते हैं। इन्हीं तीनों गुणों अर्थात् श्री ब्रह्मा जी, श्री विष्णु जी, श्री शिव जी की साधना शास्त्रा विधि रहित कही है इस शास्त्रा विधि रहित साधना को त्याग कर शास्त्राविधि अनुसार भक्ति करता है। वह पापको",
