    "कर्मयोग": "शास्त्रा विधि रहित साधना कर्म करते-करते भी करना",
    "निश्रेयसकरौ": "अमंगलकारी नहीं हैं",
    "कर्मसóयासात्": "यदि आश्रम रह कर भी काम चोर है उस कर्मसंन्याससे",
    "कर्मसóयासात": "यदि आश्रम रह कर भी काम चोर है उस कर्मसंन्याससे",
    "ब्राह्मण, क्षत्राी, वैश्य तथा शुद्र": "के व्यक्ति भी अपने स्वभाविक कर्म करते हुए परम सिद्धी अर्थात् पूर्ण मोक्ष को प्राप्त हो जाते हैं। परम सिद्धी के विषय में स्पष्ट किया है श्लोक 46 में कि जिस परमात्मा परमेश्वर से सर्व प्राणियों की उत्पति हुई है जिस से यह समस्त संसार व्याप्त है, उस परमेश्वर कि अपने-2 स्वभाविक कर्मों द्वारा पूजा करके मनुष्य परम सिद्धी को प्राप्त हो जाता हैं अर्थात् कर्म करता हुआ सत्य साधक पूर्ण मोक्ष प्राप्त करता है। अध्याय 18 श्लोक 47 में स्पष्ट किया है कि शास्त्रा विरूद्ध साधना करने वाले",
    "कर्म सन्यास": "से अपना शास्त्रा विधी अनुसार",
    "कर्म करते हुए": "साधना करने वाला श्रेष्ठ है। क्योंकि अपने कर्म करता हुआ साधक पाप को प्राप्त नहीं होता। इससे यह भी सिद्ध हुआ कि कर्म सन्यास करके हठ करना पाप है। श्लोक 48 में स्पष्ट किया है कि अपने स्वाभाविक कर्मों को नहीं त्यागना चाहिए चाहे उसमें कुछ पाप भी नजर आता है। जैसे खेती करने में जीव मरते हैं आदि-2।",
    "गीता व वेदों": "में कहा है कि पूर्ण मोक्ष के लिए किसी तत्वदर्शी सन्त की खोज करो। उसी से विनम्रता से भक्ति मार्ग प्राप्त करें। प्रमाण गीता अध्याय 4 श्लोक 34ए यजुर्वेद अध्याय 40 मन्त्रा 10 व 13 में इन दोनों में कर्मसन्यासी से कर्मयोगी अच्छा है, क्योंकि कर्मयोगी जो शास्त्रा विधि रहित साधना करता है, उसे जब कोई तत्वदर्शी संत का सत्संग प्राप्त हो जायेगा तो वह तुरन्त अपनी शास्त्रा विरुद्ध पूजा को त्याग कर शास्त्रा अनुकूल साधना पर लग कर आत्म कल्याण करा लेता है। परन्तु कर्म सन्यासी दोनों ही प्रकार के हठ योगी घर पर रहते हुए भी, जो कान-आंखें बन्द करके एक स्थान पर बैठ कर हठयोग करने वाले तथा घर त्याग कर उपरोक्त हठ योग करने वाले तत्वदर्शी संत के ज्ञान को मानवश स्वीकार नहीं करते, क्योंकि उन्हें अपने त्याग तथा हठयोग से प्राप्त सिद्धियों का अभिमान हो जाता है तथा गृह त्याग का भी अभिमान सत्यभक्ति प्राप्ति में बाधक होता है। इसलिए शास्त्राविधि रहित कर्मसन्यासी से शास्त्रा विरुद्ध कर्मयोगी साधक ही अच्छा है। यही प्रमाण गीता अध्याय 18 श्लोक 41 से 46 में कहा है कि चारों वर्णों",
    "गीता व वेदो": "में कहा है कि पूर्ण मोक्ष के लिए किसी तत्वदर्शी सन्त की खोज करो। उसी से विनम्रता से भक्ति मार्ग प्राप्त करें। प्रमाण गीता अध्याय 4 श्लोक 34ए यजुर्वेद अध्याय 40 मन्त्रा 10 व 13 में इन दोनों में कर्मसन्यासी से कर्मयोगी अच्छा है, क्योंकि कर्मयोगी जो शास्त्रा विधि रहित साधना करता है, उसे जब कोई तत्वदर्शी संत का सत्संग प्राप्त हो जायेगा तो वह तुरन्त अपनी शास्त्रा विरुद्ध पूजा को त्याग कर शास्त्रा अनुकूल साधना पर लग कर आत्म कल्याण करा लेता है। परन्तु कर्म सन्यासी दोनों ही प्रकार के हठ योगी घर पर रहते हुए भी, जो कान-आंखें बन्द करके एक स्थान पर बैठ कर हठयोग करने वाले तथा घर त्याग कर उपरोक्त हठ योग करने वाले तत्वदर्शी संत के ज्ञान को मानवश स्वीकार नहीं करते, क्योंकि उन्हें अपने त्याग तथा हठयोग से प्राप्त सिद्धियों का अभिमान हो जाता है तथा गृह त्याग का भी अभिमान सत्यभक्ति प्राप्ति में बाधक होता है। इसलिए शास्त्राविधि रहित कर्मसन्यासी से शास्त्रा विरुद्ध कर्मयोगी साधक ही अच्छा है। यही प्रमाण गीता अध्याय 18 श्लोक 41 से 46 में कहा है कि चारों वर्णों",
    "काङ्क्षति": "आकांक्षा करता है,",
