    "सर्वभूतात्मभूतात्मा": "सर्व प्राणियों के मालिक की सत्यसाधना से सर्व प्राणियों को आत्मा रूप में एक समझकर तत्वज्ञान को प्राप्त प्राणी संसार में रहता हुआ",
    "सर्वभूतात्मभूतात्म": "सर्व प्राणियों के मालिक की सत्यसाधना से सर्व प्राणियों को आत्मा रूप में एक समझकर तत्वज्ञान को प्राप्त प्राणी संसार में रहता हुआ",
    "न, लिप्यते": "लिप्त नहीं होता अर्थात् सन्तान व सम्पत्ति में आसक्त नहीं होता। क्योंकि उसे तत्वज्ञान से ज्ञान हो जाता है कि यह सन्तान व सम्पति अपनी नहीं है। जैसे कोई व्यक्ति किसी होटल में रह रहा हो, वहाँ के नौकरों व अन्य सामान जैसे टी.वी., सोफा सेट, दूरभाष, चारपाई व जिस कमरे में रह रहा है को अपना नहीं समझता उस व्यक्ति को पता होता है कि ये वस्तुऐं मेरी नहीं हंै। इसलिए उन से द्वेष भी नहीं होता तथा लगाव भी नहीं बनता तथा अपने मूल उद्देश्य को नहीं भूलता। इसलिए जिस घर में हम रह रहे हैं, इस सर्व सम्पत्ति व सन्तान को अपना न समझ कर प्रेम पूर्वक रहते हुए प्रभु प्राप्ति की लगन लगाए रखें।",
    "न, लिप्यत": "लिप्त नहीं होता अर्थात् सन्तान व सम्पत्ति में आसक्त नहीं होता। क्योंकि उसे तत्वज्ञान से ज्ञान हो जाता है कि यह सन्तान व सम्पति अपनी नहीं है। जैसे कोई व्यक्ति किसी होटल में रह रहा हो, वहाँ के नौकरों व अन्य सामान जैसे टी.वी., सोफा सेट, दूरभाष, चारपाई व जिस कमरे में रह रहा है को अपना नहीं समझता उस व्यक्ति को पता होता है कि ये वस्तुऐं मेरी नहीं हंै। इसलिए उन से द्वेष भी नहीं होता तथा लगाव भी नहीं बनता तथा अपने मूल उद्देश्य को नहीं भूलता। इसलिए जिस घर में हम रह रहे हैं, इस सर्व सम्पत्ति व सन्तान को अपना न समझ कर प्रेम पूर्वक रहते हुए प्रभु प्राप्ति की लगन लगाए रखें।",
