    "जन्तवः": "तत्वज्ञान हीनता के कारण जानवरों तुल्य सब अज्ञानी मनुष्य",
    "जन्तव": "तत्वज्ञान हीनता के कारण जानवरों तुल्य सब अज्ञानी मनुष्य",
    "मुह्यन्ति": "मोहित हो रहे हैं अर्थात् स्वभाववश शास्त्रा विधि रहित भक्ति कर्म व सांसारिक कर्म करके क्षणिक सुखों में आसक्त हो रहे हैं। जो साधक शास्त्रा विधि अनुसार भक्ति कर्म करते हैं उनके पाप को प्रभु क्षमा कर देता है अन्यथा संस्कार ही वर्तता है अर्थात् प्राप्त करता है।",
    "सतपुरुष": "द्वारा अपने मध्य से शब्द शक्ति से उत्पन्न किए। वहाँ सत्यलोक में हमें कोई कर्म नहंीं करना था तथा सर्व सुख उपलब्ध थे। हम स्वयं अपने स्वभाव वश होकर ज्योति निरंजन",
    "ब्रह्म-काल": "पर आसक्त हो कर अपने सुखदाई प्रभु से विमुख हो गए। उसी का परिणाम यह निकला कि अब हम कर्म बन्धन में स्वयं ही बन्ध गए। अब जैसे कर्म करते हैं, उसी का फल निर्धारित नियमानुसार ही प्राप्त कर रहे हैं। जो साधक शास्त्रा अनुकूल साधना करता है उसके पाप को पूर्ण परमात्मा क्षमा करता है अन्यथा संस्कार ही वर्तता है अर्थात् संस्कार ही प्राप्त करता है। नीचे के मंत्रा 16 से 28 तक शास्त्रा अनुकूल भक्ति कर्म तथा मर्यादा में रहकर पूर्ण परमात्मा को प्राप्त कर सकते हैं तथा पूर्ण प्रभु पाप क्षमा कर देता है। इसलिए कत्र्तव्य कर्म अर्थात् करने योग्य भक्ति व संसारिक कर्म करता हुआ ही पूर्ण मुक्त होता है।",
