    "ब्रह्मा-विष्णु-महेश": "भगवानों तथा 21 ब्रह्मण्ड के लोकों का मालिक है। इसलिए ईश्वरों का भी ईश्वर है। इसलिए महेश्वर कहा है तथा जो भी साधक यज्ञ या अन्य साधना",
    "तप": "करके जो सुविधा प्राप्त करता है उसका भोक्ता",
    "खाने वाला": "काल ही है। जैसे राजा बन कर आनन्द करना, नाना प्रकार के विकार करना। इन सब का आनन्द स्वयं काल भगवान मन रूप से प्राप्त करता है तथा फिर तप्त शिला पर गर्म करके उससे वासना युक्त पदार्थ निकाल कर खाता है। अज्ञानतावश नादान प्राणी इसी काल भगवान को दयालु व प्रेमी जान कर प्रसन्न है। जैसे कसाई के बकरे अपने मालिक",
    "खाने वाल": "काल ही है। जैसे राजा बन कर आनन्द करना, नाना प्रकार के विकार करना। इन सब का आनन्द स्वयं काल भगवान मन रूप से प्राप्त करता है तथा फिर तप्त शिला पर गर्म करके उससे वासना युक्त पदार्थ निकाल कर खाता है। अज्ञानतावश नादान प्राणी इसी काल भगवान को दयालु व प्रेमी जान कर प्रसन्न है। जैसे कसाई के बकरे अपने मालिक",
    "कसाई": "को देखते हैं कि वह चारा डालता है, पानी पिलाता है, गर्मी-सर्दी से बचाता है। इसलिए उसे दयालु तथा प्रेमी समझते हैं परंतु वास्तव में वह कसाई उनका काल है। सबको काटेगा, मारेगा तथा स्वार्थ सिद्ध करेगा। ऐसे ही काल भगवान दयालु दिखाई देता है परंतु सर्व प्राणियों को खाता है। इसलिए कहा है कि जो मुझ काल को ही सर्वसवा मानकर साधनारत है। उनकी शान्ति समाप्त हो जाती है अर्थात् महाकष्ट को प्राप्त होते हैं। गीता अध्याय 11 श्लोक 32 में गीता ज्ञान दाता प्रभु स्वयं कह रहा है कि मैं काल हूँ। सर्व को खाने के लिए आया हूँ। इसलिए इस अध्याय 5 श्लोक 29 का भावार्थ है कि काल को प्राप्त हो कर प्राणी को शान्ति कहाँ। इसलिए स्थान.2 पर गीता जी में कहा है पूर्ण शान्ति के लिए पूर्ण परमात्मा शान्त ब्रह्म की शरण में जा।",
