    "न, नश्यति": "नष्ट तो नहीं हो जाता? दुष्प्राय है अर्थात् भक्ति लाभ नहीं है। वह योग तो मनवश किए हुए को ही शक्य है। विचार करें फिर श्लोक 40 का यह अर्थ करना कि वह योग भ्रष्ट व्यक्ति न तो इस लोक में नष्ट होता है न परलोक में, न्याय संगत नहीं है। क्योंकि अध्याय 6 श्लोक 42 से 44 में भी यही प्रमाण है कहा है योग भ्रष्ट व्यक्ति योग भ्रष्ट होने से पूर्व के भक्ति संस्कार से कुछ दिन स्वर्ग में जाता है फिर अच्छे कुल में जन्म प्राप्त करता है परन्तु पुनः वह मानव जन्म इस लोक में अत्यन्त दुर्लभ है। यदि मानव जन्म प्राप्त हो जाता है तो पूर्व के स्वभाववश मनमाना आचरण करके तत्वज्ञान का उल्लंघन कर जाता है। अर्थात् नष्ट हो जाता है। इसलिए श्लोक 40 का अनुवाद उपरोक्त सही है। अध्याय 6 श्लोक 45 में भी स्पष्ट है।",
