    "रजगुण श्री ब्रह्मा जी, सतगुण श्री विष्णु जी, तम् गुण श्री शिव जी": "रूपी माया द्वारा जिन का ज्ञान हरा जा चुका है अर्थात् जो तीनों देवताओं की साधना करते हैं वे राक्षस स्वभाव को धारण किए हुए, मनुष्यों में नीच, दुष्कर्म करने वाले मूर्ख मुझ ब्रह्म की पूजा नहीं करते। इसी के सम्बन्ध में गीता अध्याय 7 श्लोक 20 से 23 में कहा है कि जिनका ज्ञान उपरोक्त तीनों देवताओं द्वारा हरा जा चुका है वे अपने स्वभाव वश उन्हीं देवताओं की पूजा मनोंकामना पूर्ण करने के उद्देश्य से करते हैं अर्थात् गीता ज्ञान दाता कह रहा है कि मेरे से अन्य देवताओं की पूजा करते है। जो भक्त जिस देवता की पूजा करता है उसकी श्रद्धा मैं ही उस देवता के प्रतिदृढ़ करता हूँ। उस देवताओं के पुजारी को भी मेरे द्वारा उस देवता को दी गई शक्ति से ही प्राप्त होता है। परन्तु उन मंद बुद्धि वालों अर्थात् मूर्खों का वह फल नाश्वान है। देवताओं के पूजने वाले देवताओं को प्राप्त होते हैं। मेरे भक्त मुझे प्राप्त होते हैं। भावार्थ है कि जो ब्रह्मा विष्णु तथा शिव की पूजा या अन्य किसी देव की पूजा करते हैं उन देवताओं की पूजा का फल नाश्वान है अर्थात् वह पूजा व्यर्थ है।",
