    "जो एक हजार युग की होती है": "के समाप्त होने पर दिन के प्रारम्भ में काल व दुर्गा का पुनर् जन्म होता है फिर ये एक ब्रह्मण्ड में पहले की भांति सृष्टि प्रारम्भ करते हैं। इस प्रकार परब्रह्म अर्थात् अक्षर पुरूष का एक दिन एक हजार युग का होता है तथा इतनी ही रात्राी है।",
    "काल ब्रह्म": "की आयु के समान होता है। परब्रह्म का एक दिन एक हजार युग का तथा इतनी ही रात्राी होती है। इस प्रकार परब्रह्म का एक दिन-रात दो हजार युग का हुआ। एक महिना 30 दिन का एक वर्ष 12 महिनों का तथा परब्रह्म की आयु सौ वर्ष की है। इस से सिद्ध है कि परब्रह्म अर्थात् अक्षर पुरूष भी नाश्वान है। इसलिए गीता अध्याय 15 श्लोक 16.17 तथा अध्याय 8 श्लोक 20 से 22 में किसी अन्य पूर्ण परमात्मा के विषय में कहा है जो वास्तव में अविनाशी है।",
