    "ब्रह्म-परब्रह्म तथा पूर्ण ब्रह्म": "के विषय में पूर्वोक्त श्लोक 1 से 26 में ज्ञान कहा है। उन दोनों प्रभुओं से होने वाले मोक्ष लाभ से परिचित होकर बुद्धिमान व्यक्ति मोहित नहीं होता अर्थात् काल उपासना करके धोखा नहीं खाता। इसलिए कहा है कि उस पूर्ण परमात्मा की भक्ति करने का मन बना।",
    "ब्रह्म-परब्रह्म तथा पूर्ण ब्रह्": "के विषय में पूर्वोक्त श्लोक 1 से 26 में ज्ञान कहा है। उन दोनों प्रभुओं से होने वाले मोक्ष लाभ से परिचित होकर बुद्धिमान व्यक्ति मोहित नहीं होता अर्थात् काल उपासना करके धोखा नहीं खाता। इसलिए कहा है कि उस पूर्ण परमात्मा की भक्ति करने का मन बना।",
    "ऋग्वेद, सामवेद, यर्जुवेद तथा अथर्ववेद": "से आगे का लाभ",
    "जो स्वसम वेद में वर्णित है": "प्राप्त करता है। उस के लिए वेदों वाली साधना से {दान, तप",
    "तप गीता अध्याय 17 श्लोक 14 से 16 में तीन प्रकार का कहा है": "तथा यज्ञ द्वारा} जो पुण्य होता है उस से होने वाला संसारिक लाभ प्राप्त न करके पूर्ण परमात्मा की प्राप्ति के लिए इसे ब्रह्म में त्याग कर पूर्ण मोक्ष प्राप्त करता है। क्योंकि वेदों में वर्णित विधि से पुण्य के आधार से स्वर्ग प्राप्ति होती है। पुण्य क्षीण होने के पश्चात् पुनः पाप के आधार के कष्ट भोगने पड़ते हैं। गीता अध्याय 9 श्लोक 20-21 में वेदों में वर्णित साधना से भी जन्म-मृत्यु तथा स्वर्ग-नरक का चक्र समाप्त नहीं होता। गीता अध्याय 11 श्लोक 48 व 53 में कहा है कि वेदों में वर्णित साधना से मेरी प्राप्ति नहीं है। अध्याय 11 श्लोक 54 में कहा कि मेरे में प्रवेश होने के लिए ही कहा है मोक्ष-मुक्ति के लिए नहीं जैसे गीता ज्ञान दाता प्रतिदिन एक लाख मानव शरीर धारी प्राणियों को काल रूप में खाता है। जैसा विवरण अध्याय 11 श्लोक 21 में अर्जुन आँखों देखा बता रहा है कि जो ऋषियों वे देवताओं का समूह आप का वेद मन्त्रा द्वारा गुणगान कर रहा है आप उन्हें भी खा रहे हो। वे सर्व आप में प्रवेश कर रहे हैं। कोई आपकी दाड़ों में लटक रहे हैं इसी के विषय में श्लोक 54 में कहा है। श्लोक 55 का भी यह भावार्थ है कि मेरे साधक मेरे को प्राप्त होते है। मेरे ही जाल में रह जाते हैं। उसके लिए गीता अध्याय 8 श्लोक 28 में कहा है कि पूर्ण सन्त",
    "तत्वदर्शी सन्त": "के बताए भक्ति मार्ग से साधक वेदों में वर्णित साधना का फल स्वर्ग आदि में जाकर नष्ट नहीं करता अपितु पूर्ण परमात्मा को पाने के लिए प्रयुक्त करता है। उस वेदों वाली कमाई",
    "ओं नाम का जाप पाँचों यज्ञों का फल": "को ब्रह्म में त्यागकर पूर्ण परमात्मा को प्राप्त करता है जिस कारण से पूर्ण मोक्ष प्राप्त करता है। यही प्रमाण गीता अध्याय 18 श्लोक 66 में है कहा है कि हे अर्जुन मेरे सत्रा की सर्व धाार्मिक पूजाऐं मेरे में त्याग कर तू उस एक",
    "अद्वितीय": "सर्वशक्तिमान परमश्ेवर की शरण में",
    "व्रज": "जा। फिर मैं तूझे सर्व पापों से मुक्त कर दूंगा। क्योंकि जिन पापों को भोगना था उस के प्रतिफल में सर्व पूण्य व नाम जाप की कमाई छोड़ देने से काल का ऋण समाप्त हो जाता है। इसलिए काल जाल से मुक्ति मिलती है।",
    "सृती": "मार्गों की भिन्नता को",
