    "न अवस्थितः": "स्थित नहीं हूँ। क्योंकि काल अर्थात् ज्योति निरंजन ब्रह्म अपने इक्कीसवें ब्रह्मण्ड में अलग से रहता है तथा प्रत्येक ब्रह्मण्ड में भी महाब्रह्मा, महाविष्णु, महाशिव रूप में भिन्न गुप्त रहता है। इसी का प्रमाण गीता अध्याय 7 श्लोक 12 में भी है। गीता अध्याय 13 श्लोक 17 में तथा अध्याय 18 श्लोक 61 में भी यही प्रमाण है कहा है कि पूर्ण परमात्मा प्रत्येक प्राणी के हृदय में विशेष रूप से स्थित है। वह सर्व प्राणियों को यन्त्रा की तरह भ्रमण कराता है।",
    "न अवस्थित": "स्थित नहीं हूँ। क्योंकि काल अर्थात् ज्योति निरंजन ब्रह्म अपने इक्कीसवें ब्रह्मण्ड में अलग से रहता है तथा प्रत्येक ब्रह्मण्ड में भी महाब्रह्मा, महाविष्णु, महाशिव रूप में भिन्न गुप्त रहता है। इसी का प्रमाण गीता अध्याय 7 श्लोक 12 में भी है। गीता अध्याय 13 श्लोक 17 में तथा अध्याय 18 श्लोक 61 में भी यही प्रमाण है कहा है कि पूर्ण परमात्मा प्रत्येक प्राणी के हृदय में विशेष रूप से स्थित है। वह सर्व प्राणियों को यन्त्रा की तरह भ्रमण कराता है।",
