    "भूतस्थः": "प्राणियों में स्थित है। इसी का प्रमाण गीता अध्याय 15 श्लोक 16-17 में भी है कि पूर्ण परमात्मा कोई और है, वह सर्व जगत का पालन-पोषण करता है। यही प्रमाण गीता अध्याय 13 श्लोक 17 अध्याय 18 श्लोक 61 में है कहा है कि पूर्ण परमात्मा सर्व प्राणियों के हृदय में विशेष रूप से स्थित है। वह पूर्ण परमात्मा अपनी शक्ति से सर्व प्राणियों को यन्त्रा की तरह भ्रमण कराता है।",
    "भूतस्थ": "प्राणियों में स्थित है। इसी का प्रमाण गीता अध्याय 15 श्लोक 16-17 में भी है कि पूर्ण परमात्मा कोई और है, वह सर्व जगत का पालन-पोषण करता है। यही प्रमाण गीता अध्याय 13 श्लोक 17 अध्याय 18 श्लोक 61 में है कहा है कि पूर्ण परमात्मा सर्व प्राणियों के हृदय में विशेष रूप से स्थित है। वह पूर्ण परमात्मा अपनी शक्ति से सर्व प्राणियों को यन्त्रा की तरह भ्रमण कराता है।",
