    "जिसका सम्बन्ध अध्याय 7 श्लोक 17.18 से है कि ज्ञानी मुझे अच्छा है ज्ञानी को मैं अच्छा लगता हूँ परन्तु वे मेरी अनुत्तम गति में ही आश्रित हैं": "में कहा है कि जो मुझे तथा उस पूर्ण परमात्मा को जानते हैं वे फिर मुझे भजते हैं क्योंकि गीता अध्याय 17 श्लोक 23 में कहा है कि पूर्ण परमात्मा को प्राप्ति का तीन मन्त्रा का स्मरण कहा है। ओम्-तत्-सत् ओम् जाप ब्रह्म का है। इस अध्याय 9 श्लोक 13 में उसी भाव से कहा है कि पूर्ण परमात्मा और मुझे",
    "जिसका सम्बन्ध अध्याय 7 श्लोक 17.18 से है कि ज्ञानी मुझे अच्छा है ज्ञानी को मैं अच्छा लगता हूँ परन्तु वे मेरी अनुत्तम गति में ही आश्रित है": "में कहा है कि जो मुझे तथा उस पूर्ण परमात्मा को जानते हैं वे फिर मुझे भजते हैं क्योंकि गीता अध्याय 17 श्लोक 23 में कहा है कि पूर्ण परमात्मा को प्राप्ति का तीन मन्त्रा का स्मरण कहा है। ओम्-तत्-सत् ओम् जाप ब्रह्म का है। इस अध्याय 9 श्लोक 13 में उसी भाव से कहा है कि पूर्ण परमात्मा और मुझे",
    "ब्रह्म को": "तत्व से जानकर महात्मा जन मुझे भजते हैं। उनको अन्य मन्त्रों",
    "ब्रह्म क": "तत्व से जानकर महात्मा जन मुझे भजते हैं। उनको अन्य मन्त्रों",
    "तत् व सत्": "का ज्ञान नहीं होता। इसलिए अपने आप निकाले निष्कर्ष से",
    "तत् व सत": "का ज्ञान नहीं होता। इसलिए अपने आप निकाले निष्कर्ष से",
    "दृृढव्रताः": "दृृढता के साथ कोई ज्ञान यज्ञ अर्थात् स्तूति आदि",
    "दृृढव्रता": "दृृढता के साथ कोई ज्ञान यज्ञ अर्थात् स्तूति आदि",
