    "सर्व संसार परमात्मा ही है": "जानकर साधना करते हैं। उनके लिए सर्वसवा मैं ही हूँ। अध्याय 9 श्लोक 20 से 24 में अध्याय 9 श्लोक 11 से 19 का निष्कर्ष दिया है कि वे दोनों प्रकार के साधक",
