    "ब्राह्मण, वैश्य, क्षत्राीव शुद्र कुल": "में जन्म है उस के कर्म में पाप भी समाया है। जैसे ब्राह्मण हवन करता है उसमें प्राणियों कि हिंसा होती है। वैश्य खेती व व्यापार करता है, क्षत्राी शत्राु से युद्ध करता है। शुद्र सफाई आदि सेवा करता है। प्रत्येक कर्म में हिंसा होती है। फिर भी त्यागने योग्य कर्म नहीं है। क्योंकि इन कर्मों में हिंसा करना उद्देश्य नहीं होता। यदि देखा जाए तो सर्व उपरोक्त कर्म दोष युक्त हैं। तो भी प्रभु आज्ञा होने से कत्र्तव्य कर्म हैं। यही प्रमाण अध्याय 4 श्लोक 21 में है कि शरीर समबन्धि कर्म करता हुआ पाप को प्राप्त नहीं होता। गीता अध्याय 18 श्लोक 56 में भी है।",
